    /// <summary>
    /// The chatMode parameter determines the chat modes available to Amazon Q Business users: o RETRIEVAL_MODE - If you choose this mode, Amazon Q generates re- sponses solely from the data sources connected and indexed by the application. If an answer is not found in the data sources or there are no data sources available, Amazon Q will respond with a "No Answer Found " message, unless LLM knowledge has been enabled. In that case, Amazon Q will generate a response from the LLM knowledge o CREATOR_MODE - By selecting this mode, you can choose to generate responses only from the LLM knowledge. You can also attach files and have Amazon Q generate a response based on the data in those files. If the attached files do not contain an answer for the query, Amazon Q will automatically fall back to generating a re- sponse from the LLM knowledge. o PLUGIN_MODE - By selecting this mode, users can choose to use plu- gins in chat to get their responses. NOTE: If none of the modes are selected, Amazon Q will only respond using the information from the attached files. For more information, see Admin controls and guardrails , Plugins , and Response sources . Possible values: o RETRIEVAL_MODE o CREATOR_MODE o PLUGIN_MODE
    /// </summary>
    [CliOption("--chat-mode")]
    public AwsQbusinessChatSyncChatMode? ChatMode { get; set; }

